        parent_lower = path_lower[:idx]
        last_comp_lower = path_lower[idx+1:]

    if not keywords:
        return True

    pos = 0
    for i, kw in enumerate(keywords):
        kw_lower = kw.lower()
        is_last = (i == len(keywords)-1)
        ends_with_slash = kw_lower.endswith('/')
        if ends_with_slash:
            X = kw_lower[:-1]
            if is_last:
                if not parent_lower.endswith(X):
                    return False
            else:
                search_str = X + '/'
                found_idx = path_lower.find(search_str, pos)
                if found_idx == -1:
                    return False
                pos = found_idx + len(search_str)
        else:
            if '/' in kw_lower:
                found_idx = path_lower.find(kw_lower, pos)
                if found_idx == -1:
                    return False
                if is_last:
                    last_seg = kw_lower.rsplit('/',1)[-1]
                    if last_seg not in last_comp_lower:
                        return False
                pos = found_idx + len(kw_lower)
            else:
                found_idx = path_lower.find(kw_lower, pos)
                if found_idx == -1:
                    return False
                if is_last:
                    if kw_lower not in last_comp_lower:
                        return False
                pos = found_idx + len(kw_lower)
