use clap::{Parser, Subcommand, ValueEnum};

#[derive(Parser)]
#[command(name = "zoxide", version = "0.9.9", author = "Ajeet D'Souza <98ajeet@gmail.com>", about = "A smarter cd command for your terminal", long_about = None)]
