    #[arg(value_name = "PATHS")]
    paths: Vec<String>,
}

#[derive(Clone, Debug)]
struct DirEntry {
    path: String,
    rank: f64,
    last_accessed: u64,
}

fn get_data_dir() -> PathBuf {
    if let Ok(dir) = env::var("_ZO_DATA_DIR") {
        return PathBuf::from(dir);
    }
    if let Ok(dir) = env::var("XDG_DATA_HOME") {
        let mut p = PathBuf::from(dir);
        p.push("zoxide");
        return p;
    }
    // Default: $HOME/.local/share/zoxide
    let home = env::var("HOME").unwrap_or_else(|_| ".".to_string());
    let mut p = PathBuf::from(home);
    p.push(".local");
    p.push("share");
    p.push("zoxide");
    p
}

fn get_db_path() -> PathBuf {
    let mut dir = get_data_dir();
    // If _ZO_DATA_DIR is set, db is directly inside it (as observed)
    if env::var("_ZO_DATA_DIR").is_ok() {
        dir.push("db.zo");
        dir
    } else {
        dir.push("db.zo");
        dir
    }
}

fn read_db() -> Vec<DirEntry> {
    let db_path = get_db_path();
    if !db_path.exists() {
        return Vec::new();
    }
    let data = match fs::read(&db_path) {
        Ok(d) => d,
        Err(_) => return Vec::new(),
    };
    if data.len() < 12 {
        return Vec::new();
    }
    let version = u32::from_le_bytes([data[0], data[1], data[2], data[3]]);
    if version != 3 {
        // For simplicity, treat as empty if version mismatch
        return Vec::new();
    }
    let count = u64::from_le_bytes([
        data[4], data[5], data[6], data[7], data[8], data[9], data[10], data[11],
    ]);
    let mut offset = 12usize;
    let mut entries = Vec::new();
    for _ in 0..count {
        if offset + 8 > data.len() {
            break;
        }
        let len = u64::from_le_bytes([
            data[offset], data[offset+1], data[offset+2], data[offset+3],
            data[offset+4], data[offset+5], data[offset+6], data[offset+7],
        ]) as usize;
        offset += 8;
        if offset + len > data.len() {
            break;
        }
        let path_bytes = &data[offset..offset+len];
        let path_str = String::from_utf8_lossy(path_bytes).to_string();
        offset += len;
        if offset + 8 > data.len() {
            break;
        }
        let rank = f64::from_le_bytes([
            data[offset], data[offset+1], data[offset+2], data[offset+3],
            data[offset+4], data[offset+5], data[offset+6], data[offset+7],
        ]);
        offset += 8;
        if offset + 8 > data.len() {
            break;
        }
        let last = u64::from_le_bytes([
            data[offset], data[offset+1], data[offset+2], data[offset+3],
            data[offset+4], data[offset+5], data[offset+6], data[offset+7],
        ]);
        offset += 8;
        entries.push(DirEntry {
            path: path_str,
            rank,
            last_accessed: last,
        });
    }
    entries
}

fn write_db(entries: &[DirEntry]) -> io::Result<()> {
    let db_path = get_db_path();
    if let Some(parent) = db_path.parent() {
        fs::create_dir_all(parent)?;
    }
    let mut data = Vec::new();
    data.extend_from_slice(&3u32.to_le_bytes());
    data.extend_from_slice(&(entries.len() as u64).to_le_bytes());
    for e in entries {
        let path_bytes = e.path.as_bytes();
        data.extend_from_slice(&(path_bytes.len() as u64).to_le_bytes());
        data.extend_from_slice(path_bytes);
        data.extend_from_slice(&e.rank.to_le_bytes());
        data.extend_from_slice(&e.last_accessed.to_le_bytes());
    }
    fs::write(&db_path, data)
}

fn current_timestamp() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_secs()
}

fn get_maxage() -> f64 {
    if let Ok(val) = env::var("_ZO_MAXAGE") {
        if let Ok(v) = val.parse::<f64>() {
            return v;
        }
    }
    10000.0
}

fn get_exclude_dirs() -> Vec<String> {
    let mut patterns = Vec::new();
    // Default excludes $HOME
    if env::var("_ZO_EXCLUDE_DIRS").is_err() {
        if let Ok(home) = env::var("HOME") {
            patterns.push(home);
        }
    }
    if let Ok(val) = env::var("_ZO_EXCLUDE_DIRS") {
        // Split by ':' on unix, ';' on windows
        #[cfg(windows)]
        let sep = ';';
        #[cfg(not(windows))]
        let sep = ':';
        for p in val.split(sep) {
            if !p.is_empty() {
                patterns.push(p.to_string());
            }
        }
    }
    patterns
}

fn is_excluded(path: &str, exclude_patterns: &[String]) -> bool {
    for pat in exclude_patterns {
        // Use glob crate pattern matching
        // The glob crate's Pattern::matches requires pattern to be valid
        // We observed that * matches any chars including slash, but glob crate's * does NOT match slash.
        // However we observed * DOES match slash in practice for exclude. Let's see if we can use glob with custom matching that allows * to match slash.
        // We will implement a simple glob matcher that matches whole path and allows * to match any chars including slash, ? to match any single char except slash, and ** to match any chars including slash but must be its own component.
        // But also need to handle ** validation.
        // For simplicity, we will use glob crate for validation, but for matching we will use our custom matcher that allows * to match slash.
        // First, validate pattern using glob::Pattern::new – if it fails, we should error like original: "zoxide: invalid glob in _ZO_EXCLUDE_DIRS: <pat> \n\nCaused by:\n    <err>"
        // Original error prints to stderr and exits? Let's check behavior for invalid glob.
        // In our earlier test, invalid glob **a printed error and exit code? It printed error message and didn't add? Let's check.
        // We should implement validation.
        match glob::Pattern::new(pat) {
            Ok(_) => {},
            Err(e) => {
                eprintln!("zoxide: invalid glob in _ZO_EXCLUDE_DIRS: {}", pat);
                eprintln!("\nCaused by:\n    {}", e);
                std::process::exit(1);
            }
        }
        if glob_match(pat, path) {
            return true;
        }
    }
    false
}

fn glob_match(pattern: &str, path: &str) -> bool {
    // Convert glob pattern to regex where * matches .*, ? matches [^/], ** matches .*
    // But also handle **/ and /**/ etc.
    // For simplicity, we implement matching that allows * to match any chars including slash, ? to match [^/].
    // We also need to support ** as separate component: it matches any sequence including slash, possibly empty? But for exclude, /tmp/** should NOT match /tmp itself, so ** should NOT match empty when it's after slash? Actually /tmp/** target /tmp => NOT excluded, so ** does not match empty. So ** should match one or more? Or at least one char? Let's think.
    // Pattern /tmp/**: we said it should match /tmp/a but not /tmp itself. If ** matches .*, then /tmp/** regex ^/tmp/.*$ would not match /tmp (needs slash + something), so it would NOT match /tmp, but WOULD match /tmp/a (.* = a). So ** matching .* including empty would still not match /tmp because /tmp/** has slash before **, so pattern is "/tmp/" + ".*" + ""? If .* can be empty, then "/tmp/" + "" = "/tmp/" which is not "/tmp". So it wouldn't match /tmp. Good.
    // Pattern /tmp/b/*: "/tmp/b/" + ".*" => matches "/tmp/b/c" (.*=c) and "/tmp/b/c/d" (.*=c/d), but not "/tmp/b" (needs slash). Good.
    // Pattern /tmp/b/**: "/tmp/b/" + ".*" => same as above, matches c and c/d, but not b itself. Good.
    // Pattern *: ".*" matches everything, including "/tmp/qqq/b" – yes.
    // Pattern *a: ".*a" matches any path ending with a – yes.
    // Pattern */a: ".*/a" matches any path ending with "/a" – matches "/tmp/qqq/b/a" and "/tmp/qqq/a", but not "/tmp/qqq/b/c/d" (ends with /d). Good.
