        let mut s_idx = 0;
        let mut star_idx: Option<usize> = None;
        let mut s_tmp_idx = 0;

        while s_idx < path.len() {
            if p_idx < pat.len() {
                let pc = pat[p_idx];
                let sc = path[s_idx];
