                    }
                    star_idx = Some(p_idx - 1);
                    s_tmp_idx = s_idx;
                    continue;
                } else {
                    if pc == sc {
                        p_idx += 1;
                        s_idx += 1;
                        continue;
                    }
                }
            }
            // Mismatch, but if we have star, backtrack
            if let Some(si) = star_idx {
                p_idx = si + 1;
                s_tmp_idx += 1;
                s_idx = s_tmp_idx;
