            }
        } else {
            map.insert(e.path.clone(), e);
        }
    }
    map.into_values().collect()
}

fn add_dirs(paths: Vec<String>, score: Option<f64>) {
    let exclude_patterns = get_exclude_dirs();
    let now = current_timestamp();
    let inc = score.unwrap_or(1.0);

    let mut db = read_db();

    for p in paths {
        let path_obj = Path::new(&p);
        // Check if directory exists
        if !path_obj.is_dir() {
            eprintln!("zoxide: not a directory: {}", p);
            std::process::exit(1);
        }
        // Canonicalize if resolve symlinks
        let mut final_path = p.clone();
        if env::var("_ZO_RESOLVE_SYMLINKS").map(|v| v == "1").unwrap_or(false) {
            if let Ok(canonical) = fs::canonicalize(&p) {
                final_path = canonical.to_string_lossy().to_string();
            }
        } else {
            // Normalize? Use absolute? Original zoxide stores as given? But it likely stores absolute? Let's check: when adding /tmp/foo, it stored /tmp/foo as given, not canonicalized unless resolve. So keep as given, but we should make it absolute? The binary stores as given path, but we should ensure it's absolute? In tests, we added /tmp/foo and it stored /tmp/foo. So keep as given if absolute, else make absolute? For simplicity, if path is relative, make it absolute via current_dir + path? Original zoxide likely uses current_dir? But we can just use canonicalize without resolve? Actually without resolve, they use pwd -L logic, which is logical path. For add command, they probably use the path as given, but if relative, they make it absolute? Let's check original behavior for relative path: earlier we tested z foo/ as relative? The binary's add requires path exists and is directory, but does it store relative or absolute? In our earlier tests, we always used absolute. For simplicity, we will store as given if absolute, else join with current_dir and make absolute (using current_dir + path). And we will not canonicalize unless resolve.

            // Make absolute if not absolute
            let path_buf = PathBuf::from(&final_path);
            if !path_buf.is_absolute() {
                if let Ok(cwd) = env::current_dir() {
                    let abs = cwd.join(path_buf);
                    // Normalize .. and . without resolving symlinks?
                    // For simplicity, we can use abs.to_string_lossy and then clean?
                    // We'll just use abs canonicalize? But that would resolve symlinks even when not requested. So we need to normalize logically.
                    // Use path cleaning: remove . and .. components
                    let mut components = Vec::new();
                    for comp in abs.components() {
                        use std::path::Component;
                        match comp {
                            Component::ParentDir => { components.pop(); },
                            Component::CurDir => {},
                            _ => components.push(comp),
                        }
                    }
                    let mut cleaned = PathBuf::new();
                    for c in components {
                        cleaned.push(c);
                    }
                    final_path = cleaned.to_string_lossy().to_string();
                }
            }
        }

        // Exclude check
        if is_excluded(&final_path, &exclude_patterns) {
            continue;
        }

        // Find existing entry
        if let Some(existing) = db.iter_mut().find(|e| e.path == final_path) {
            existing.rank += inc;
            existing.last_accessed = now;
        } else {
            db.push(DirEntry {
                path: final_path,
                rank: inc,
                last_accessed: now,
            });
        }
    }

    // Aging
    let maxage = get_maxage();
    let total: f64 = db.iter().map(|e| e.rank).sum();
    if total > maxage {
        let factor = 0.9 * maxage / total;
        for e in db.iter_mut() {
            e.rank *= factor;
        }
        // Remove entries with rank < 1.0? From earlier tests, when rank <1 after aging, entries were removed? In one test, we had entries with rank 1 and 100, after aging with maxage 100, the low rank entry was removed? Let's check:
        // Earlier we had 1 entry rank 1 and 5 entries rank 100, total 501, maxage 100, factor 90/501 ~0.179, low rank becomes 0.179 <1, and it was removed (we saw only high entries remained, low removed). So yes, remove entries with rank <1.0 after aging.
        db.retain(|e| e.rank >= 1.0);
    }

    if let Err(e) = write_db(&db) {
        eprintln!("zoxide: could not write database: {}", e);
        std::process::exit(1);
    }
}

fn remove_dirs(paths: Vec<String>) {
    if paths.is_empty() {
        return;
    }
    let mut db = read_db();
    let mut to_remove = Vec::new();
    for p in paths {
        // For remove, path can be absolute or relative? Original remove likely takes exact path match? Let's check: we added /tmp/a and removed /tmp/a, it worked. Does remove support glob? No, exact match.
        // Also need to handle symlink resolve? Probably same as add: if resolve is set, canonicalize?
        let mut final_path = p.clone();
        if env::var("_ZO_RESOLVE_SYMLINKS").map(|v| v == "1").unwrap_or(false) {
            if let Ok(canonical) = fs::canonicalize(&p) {
                final_path = canonical.to_string_lossy().to_string();
            }
        }
        to_remove.push(final_path);
    }
    db.retain(|e| !to_remove.contains(&e.path));
    if let Err(e) = write_db(&db) {
        eprintln!("zoxide: could not write database: {}", e);
        std::process::exit(1);
    }
}

fn query_score(rank: f64, last: u64, now: u64) -> f64 {
    let delta = now.saturating_sub(last);
    let factor = if delta < 3600 {
        4.0
    } else if delta < 86400 {
        2.0
    } else if delta < 604800 {
        0.5
    } else {
        0.25
    };
    rank * factor
}

fn matches_keywords(path: &str, keywords: &[String]) -> bool {
    if keywords.is_empty() {
        return true;
    }
    let path_lower = path.to_lowercase();
    // Find last component start
    let last_slash = path.rfind('/');
    let (parent, last_comp) = if let Some(idx) = last_slash {
        (&path[..idx], &path[idx+1..])
    } else {
        ("", path)
    };
    let parent_lower = parent.to_lowercase();
    let last_lower = last_comp.to_lowercase();

    // For single keyword ending with slash, special handling: parent ends with keyword without slash
    if keywords.len() == 1 && keywords[0].ends_with('/') {
        let kw = keywords[0].trim_end_matches('/').to_lowercase();
        // Parent must end with kw
        if kw.is_empty() {
            return true;
        }
        return parent_lower.ends_with(&kw);
    }

    // For general case, we need to search keywords in order
    // We will implement as: for each keyword in order, find it as substring in path (case-insensitive) after previous position
    // For last keyword:
    //   If keyword ends with '/', then we need to find X + '/' in path? Actually for non-last trailing slash, we search X + '/'?
    //   If keyword does NOT end with '/', and contains '/', then need path contains keyword and last segment in last component AND occurrence's last segment within last component
    //   If keyword does NOT contain '/', then last component must contain keyword and occurrence must be within last component

    let mut pos = 0usize;
    // For last component checks, we need to ensure last keyword's occurrence is within last component region for non-trailing slash
    // We'll handle last keyword specially

    for (i, kw) in keywords.iter().enumerate() {
        let is_last = i == keywords.len() - 1;
        let kw_lower = kw.to_lowercase();
        let ends_slash = kw_lower.ends_with('/');

        if ends_slash {
            let X = kw_lower.trim_end_matches('/').to_string();
            if X.is_empty() {
                // Keyword "/" – should match everything? From earlier, "/" matched all
                // For single "/", we return true (since parent suffix of "/" is empty? Actually "/" alone should match all? We observed "/" matched all)
                // For "/" we will treat as matching everything
                // Find "/" in path
                if let Some(idx) = path_lower[pos..].find('/') {
                    pos += idx + 1;
                } else {
                    return false;
                }
                continue;
            }
            if is_last {
                // Parent must end with X
                if !parent_lower.ends_with(&X) {
                    return false;
                }
                // Also need to ensure previous keywords were found before parent's suffix start? For simplicity, we have pos tracking for previous keywords, which should be <= parent len
                // Check that pos <= parent_lower.len() (since parent is prefix of path before last component)
                // Actually parent length in path_lower is parent_lower.len(), and last component starts after that +1
                // So previous pos should be <= parent_lower.len()
                // If previous keywords were found, pos is after them, which should be <= parent len if they were within parent
                // But what if previous keyword was found after parent? That would be out of order? Let's just check that pos <= path_lower.len()
                // For now, we already have pos tracking, and we will not update pos for last trailing slash (since its position is at parent end)
                // We should ensure that pos <= parent_lower.len() (since previous keywords must be before parent end)
                // Actually parent suffix starts at parent_len - X_len, so previous pos should be <= parent_len - X_len + something? Let's approximate: previous pos should be <= parent_lower.len()
                // For query "a/ e" with path a/b/c/d/e: a/ found at beginning pos=2, parent len of e's path is len("a/b/c/d") = 7, pos=2 <=7, so ok
                continue;
            } else {
                // Non-last trailing slash: search for X + '/' in path after pos
                let search = X.clone() + "/";
                if let Some(idx) = path_lower[pos..].find(&search) {
                    pos += idx + search.len();
                } else {
                    return false;
                }
            }
        } else {
            // No trailing slash
            if kw_lower.contains('/') {
                // Contains slash
                if let Some(idx) = path_lower[pos..].find(&kw_lower) {
                    // For last keyword, need last segment within last component
                    if is_last {
                        let last_seg = kw_lower.rsplit('/').last().unwrap_or("");
                        if !last_lower.contains(last_seg) {
                            return false;
                        }
                        // Also need that the occurrence's last segment is within last component region
                        // Find position of last segment within the occurrence
                        let last_slash_in_kw = kw_lower.rfind('/').unwrap();
                        let seg_start_in_path = pos + idx + last_slash_in_kw + 1;
                        let last_comp_start = path_lower.rfind('/').map(|i| i+1).unwrap_or(0);
                        if seg_start_in_path < last_comp_start {
                            // Last segment not within last component at this occurrence, try to find next occurrence that satisfies?
                            // We should search for next occurrence that satisfies condition
                            // For simplicity, continue searching for next occurrence
                            let mut next_pos = pos + idx + 1;
                            loop {
                                if let Some(next_idx) = path_lower[next_pos..].find(&kw_lower) {
                                    let abs_idx = next_pos + next_idx;
                                    let seg_start = abs_idx + last_slash_in_kw + 1;
                                    if seg_start >= last_comp_start && last_lower.contains(last_seg) {
                                        pos = abs_idx + kw_lower.len();
                                        break;
                                    } else {
                                        next_pos = abs_idx + 1;
                                        continue;
                                    }
                                } else {
                                    return false;
                                }
                            }
                        } else {
                            pos += idx + kw_lower.len();
                        }
                    } else {
                        pos += idx + kw_lower.len();
                    }
                } else {
                    return false;
                }
            } else {
                // No slash
                if is_last {
                    // Need to find occurrence within last component
                    // Search for kw in last component after pos that is within last component region
                    // First, ensure pos <= last_comp_start + something? Actually last keyword must be in last component, so its occurrence must start >= last_comp_start
                    // We should search in last_comp, not whole path, but also ensure earlier keywords were before it.
                    // Find kw in last_lower
                    if !last_lower.contains(&kw_lower) {
                        return false;
                    }
                    // For order, we need to ensure that earlier keywords were found before last_comp_start + position of kw in last_comp
                    // We can find first occurrence of kw in path that is within last component and after pos
                    let mut found = false;
                    let mut search_pos = pos;
                    while let Some(idx) = path_lower[search_pos..].find(&kw_lower) {
                        let abs_idx = search_pos + idx;
                        if abs_idx >= last_comp_start {
                            // Found within last component
                            pos = abs_idx + kw_lower.len();
                            found = true;
                            break;
                        } else {
                            // Found before last component, but since it's last keyword, it must be in last component, so continue searching
                            search_pos = abs_idx + 1;
                        }
                    }
                    if !found {
                        return false;
                    }
                } else {
                    if let Some(idx) = path_lower[pos..].find(&kw_lower) {
                        pos += idx + kw_lower.len();
                    } else {
                        return false;
                    }
                }
            }
        }
    }
    true
}

