        });
    }

    // Apply exclude filter
    if let Some(ex) = &exclude_path {
        entries.retain(|(e, _)| e.path != *ex);
    }

    // Apply keywords filter
    let keywords = args.keywords;
    // Handle "--" separator? clap should handle, but our QueryArgs includes keywords that may include "--"? Actually clap's -- should be handled. In original, they use "--" to separate keywords from options, and also to allow keywords starting with "-". Our clap will handle.

    // Filter by keywords
    if !keywords.is_empty() {
