        // In earlier tests, "./executable query --list foo" with no match returned exit 0 and printed nothing? We had test with nonexist and exit 0. Let's check again logic:
        // Original: query without --list and no match => error "zoxide: no match found" exit 1
        // With --list, no match => print nothing and exit 0? We observed for query list with nonexist, it had exit 0? Let's recall.
        // In one test: "./executable query --list --score foo" with nonexist returned exit 0 and printed nothing? Actually earlier we had test that query --list nonexist returned exit 0? Let's assume.
        // We'll implement: if entries empty and --list, print nothing exit 0. If not list, error.
        if !args.list && !args.interactive {
            eprintln!("zoxide: no match found");
            std::process::exit(1);
        }
    }

    if args.interactive {
        // Use fzf
        let fzf_opts = env::var("_ZO_FZF_OPTS").unwrap_or_default();
        // Prepare input for fzf: list of paths with score? Probably list with score? Let's check original interactive: it shows list with fzf selection.
        // We need to run fzf with entries.
        // For simplicity, if fzf not available, fallback to first entry?

        // Check if fzf exists
        let fzf_bin = "fzf";
