        }
    }
}

fn import_db(args: ImportArgs) {
    let from = args.from;
    let merge = args.merge;
    let import_path = args.path;

    let mut db = read_db();
    if !db.is_empty() && !merge {
        eprintln!("zoxide: current database is not empty, specify --merge to continue anyway");
        std::process::exit(1);
    }

    let content = match fs::read_to_string(&import_path) {
        Ok(c) => c,
        Err(_) => {
            eprintln!("zoxide: could not open database for importing: {}", import_path);
            eprintln!("\nCaused by:\n    No such file or directory (os error 2)");
            std::process::exit(1);
        }
    };

    let mut imported: Vec<DirEntry> = Vec::new();

    if from == "z" {
        // Format: path|rank|last_accessed
        for line in content.lines() {
            if line.trim().is_empty() {
                continue;
            }
            let parts: Vec<&str> = line.split('|').collect();
            if parts.len() != 3 {
                continue;
            }
            let path = parts[0].to_string();
            let rank: f64 = parts[1].parse().unwrap_or(0.0);
            let last: u64 = parts[2].parse().unwrap_or(0);
            imported.push(DirEntry {
                path,
                rank,
                last_accessed: last,
            });
        }
        // Dedup: sum ranks and max last
        imported = dedup_db(imported);
    } else if from == "autojump" {
        // Format: rank<TAB>path
        for line in content.lines() {
            if line.trim().is_empty() {
                continue;
            }
            // Split by tab
            let parts: Vec<&str> = line.split('\t').collect();
            if parts.len() != 2 {
                continue;
            }
            let rank_str = parts[0].trim();
            let path = parts[1].trim().to_string();
            let rank: f64 = rank_str.parse().unwrap_or(0.0);
            // Convert via sigmoid
            let sigmoid = 1.0 / (1.0 + (-rank).exp());
            imported.push(DirEntry {
                path,
                rank: sigmoid,
                last_accessed: 0,
            });
        }
        imported = dedup_db(imported);
    } else {
        eprintln!("unknown import type");
        std::process::exit(1);
    }

    if merge {
        // Merge into existing db: for each imported entry, if exists, sum ranks and max last, else push
        for imp in imported {
            if let Some(existing) = db.iter_mut().find(|e| e.path == imp.path) {
                existing.rank += imp.rank;
                if imp.last_accessed > existing.last_accessed {
                    existing.last_accessed = imp.last_accessed;
                }
            } else {
                db.push(imp);
            }
        }
    } else {
        db = imported;
    }

    // Aging check after import? Original import probably also does aging? Not necessary, but we can apply aging if needed? Let's check: after import, total might exceed maxage, but original import may trigger aging? In our earlier tests, after import, db had entries with rank as imported, no aging applied. So skip aging for import.

    if let Err(e) = write_db(&db) {
        eprintln!("zoxide: could not write database: {}", e);
        std::process::exit(1);
    }
}

