fn get_data_dir() -> PathBuf {
    if let Ok(dir) = env::var("_ZO_DATA_DIR") {
        return PathBuf::from(dir);
    }
    if let Ok(dir) = env::var("XDG_DATA_HOME") {
        let mut p = PathBuf::from(dir);
        p.push("zoxide");
        return p;
    }
    let home = env::var("HOME").unwrap_or_else(|_| ".".to_string());
    let mut p = PathBuf::from(home);
    p.push(".local");
    p.push("share");
    p.push("zoxide");
    p
}

fn get_db_path() -> PathBuf {
    let mut dir = get_data_dir();
    dir.push("db.zo");
    dir
}

fn read_db() -> Vec<DirEntry> {
    let db_path = get_db_path();
    if !db_path.exists() {
        return Vec::new();
    }
    let data = match fs::read(&db_path) {
        Ok(d) => d,
        Err(_) => return Vec::new(),
    };
    if data.len() < 12 {
        return Vec::new();
    }
    let version = u32::from_le_bytes([data[0], data[1], data[2], data[3]]);
    if version != 3 {
        return Vec::new();
    }
    let count = u64::from_le_bytes([
        data[4], data[5], data[6], data[7], data[8], data[9], data[10], data[11],
    ]);
    let mut offset = 12usize;
    let mut entries = Vec::new();
    for _ in 0..count {
        if offset + 8 > data.len() { break; }
        let len = u64::from_le_bytes([
            data[offset], data[offset+1], data[offset+2], data[offset+3],
            data[offset+4], data[offset+5], data[offset+6], data[offset+7],
        ]) as usize;
        offset += 8;
        if offset + len > data.len() { break; }
        let path_str = String::from_utf8_lossy(&data[offset..offset+len]).to_string();
        offset += len;
        if offset + 8 > data.len() { break; }
        let rank = f64::from_le_bytes([
            data[offset], data[offset+1], data[offset+2], data[offset+3],
            data[offset+4], data[offset+5], data[offset+6], data[offset+7],
        ]);
        offset += 8;
        if offset + 8 > data.len() { break; }
        let last = u64::from_le_bytes([
            data[offset], data[offset+1], data[offset+2], data[offset+3],
            data[offset+4], data[offset+5], data[offset+6], data[offset+7],
        ]);
        offset += 8;
        entries.push(DirEntry { path: path_str, rank, last_accessed: last });
    }
    entries
}

fn write_db(entries: &[DirEntry]) -> std::io::Result<()> {
    let db_path = get_db_path();
    if let Some(parent) = db_path.parent() {
        fs::create_dir_all(parent)?;
    }
    let mut data = Vec::new();
    data.extend_from_slice(&3u32.to_le_bytes());
    data.extend_from_slice(&(entries.len() as u64).to_le_bytes());
    for e in entries {
        let pb = e.path.as_bytes();
        data.extend_from_slice(&(pb.len() as u64).to_le_bytes());
        data.extend_from_slice(pb);
        data.extend_from_slice(&e.rank.to_le_bytes());
        data.extend_from_slice(&e.last_accessed.to_le_bytes());
    }
    fs::write(&db_path, data)
}

fn current_timestamp() -> u64 {
    SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_secs()
}

fn get_maxage() -> f64 {
    if let Ok(v) = env::var("_ZO_MAXAGE") {
        if let Ok(f) = v.parse::<f64>() { return f; }
    }
    10000.0
}

fn get_exclude_patterns() -> Vec<String> {
    let mut pats = Vec::new();
    if env::var("_ZO_EXCLUDE_DIRS").is_err() {
        if let Ok(home) = env::var("HOME") {
            pats.push(home);
        }
    }
    if let Ok(val) = env::var("_ZO_EXCLUDE_DIRS") {
        #[cfg(windows)] let sep = ';';
        #[cfg(not(windows))] let sep = ':';
        for p in val.split(sep) {
            if !p.is_empty() { pats.push(p.to_string()); }
        }
    }
    pats
}

fn glob_match(pattern: &str, path: &str) -> bool {
    // Custom glob matching where * matches any sequence including '/', ? matches [^/]
    // Implement via simple recursion
    fn match_pat(pat: &[char], s: &[char]) -> bool {
        let mut p_i = 0;
        let mut s_i = 0;
        let mut star: Option<usize> = None;
        let mut s_tmp = 0;
        while s_i < s.len() {
            if p_i < pat.len() {
                let pc = pat[p_i];
                if pc == '?' {
                    if s[s_i] == '/' {
                        if let Some(si) = star {
                            p_i = si + 1;
                            s_tmp += 1;
                            s_i = s_tmp;
                            continue;
                        } else {
                            return false;
                        }
                    } else {
                        p_i += 1;
                        s_i += 1;
                        continue;
                    }
                } else if pc == '*' {
                    // skip consecutive *
                    while p_i < pat.len() && pat[p_i] == '*' {
                        p_i += 1;
                    }
                    if p_i == pat.len() {
                        return true;
                    }
                    star = Some(p_i - 1);
                    s_tmp = s_i;
                    continue;
                } else {
                    if pc == s[s_i] {
                        p_i += 1;
                        s_i += 1;
                        continue;
                    }
                }
            }
            if let Some(si) = star {
                p_i = si + 1;
                s_tmp += 1;
                s_i = s_tmp;
                continue;
            } else {
                return false;
            }
        }
        while p_i < pat.len() && pat[p_i] == '*' {
            p_i += 1;
        }
        p_i == pat.len()
    }
    let pat_chars: Vec<char> = pattern.chars().collect();
    let path_chars: Vec<char> = path.chars().collect();
    match_pat(&pat_chars, &path_chars)
}

fn is_excluded(path: &str, pats: &[String]) -> bool {
    for pat in pats {
        match glob::Pattern::new(pat) {
            Ok(_) => {},
            Err(e) => {
                eprintln!("zoxide: invalid glob in _ZO_EXCLUDE_DIRS: {}", pat);
                eprintln!("\nCaused by:\n    {}", e);
                std::process::exit(1);
            }
        }
        if glob_match(pat, path) {
            return true;
        }
    }
    false
}

fn dedup_db(mut entries: Vec<DirEntry>) -> Vec<DirEntry> {
    let mut map: HashMap<String, DirEntry> = HashMap::new();
    for e in entries {
        if let Some(existing) = map.get_mut(&e.path) {
            existing.rank += e.rank;
            if e.last_accessed > existing.last_accessed {
                existing.last_accessed = e.last_accessed;
            }
        } else {
            map.insert(e.path.clone(), e);
        }
    }
    map.into_values().collect()
}

fn add_dirs(paths: Vec<String>, score: Option<f64>) {
    let exclude_pats = get_exclude_patterns();
    let now = current_timestamp();
    let inc = score.unwrap_or(1.0);
    let mut db = read_db();
    for p in paths {
        let path_obj = Path::new(&p);
        if !path_obj.is_dir() {
            eprintln!("zoxide: not a directory: {}", p);
            std::process::exit(1);
        }
        let mut final_path = p.clone();
        if env::var("_ZO_RESOLVE_SYMLINKS").map(|v| v == "1").unwrap_or(false) {
            if let Ok(can) = fs::canonicalize(&p) {
                final_path = can.to_string_lossy().to_string();
            }
        } else {
            let buf = PathBuf::from(&final_path);
            if !buf.is_absolute() {
                if let Ok(cwd) = env::current_dir() {
                    let abs = cwd.join(buf);
                    let mut comps = Vec::new();
                    for comp in abs.components() {
                        use std::path::Component;
                        match comp {
                            Component::ParentDir => { comps.pop(); },
                            Component::CurDir => {},
                            _ => comps.push(comp),
                        }
                    }
                    let mut cleaned = PathBuf::new();
                    for c in comps { cleaned.push(c); }
                    final_path = cleaned.to_string_lossy().to_string();
                }
            }
        }
        if is_excluded(&final_path, &exclude_pats) {
            continue;
        }
        if let Some(existing) = db.iter_mut().find(|e| e.path == final_path) {
            existing.rank += inc;
            existing.last_accessed = now;
        } else {
            db.push(DirEntry { path: final_path, rank: inc, last_accessed: now });
        }
    }
    let maxage = get_maxage();
    let total: f64 = db.iter().map(|e| e.rank).sum();
    if total > maxage {
        let factor = 0.9 * maxage / total;
        for e in db.iter_mut() { e.rank *= factor; }
        db.retain(|e| e.rank >= 1.0);
    }
    if let Err(e) = write_db(&db) {
        eprintln!("zoxide: could not write database: {}", e);
        std::process::exit(1);
    }
}

fn remove_dirs(paths: Vec<String>) {
    if paths.is_empty() { return; }
    let mut db = read_db();
    let mut to_remove = Vec::new();
    for p in paths {
        let mut fp = p.clone();
        if env::var("_ZO_RESOLVE_SYMLINKS").map(|v| v == "1").unwrap_or(false) {
            if let Ok(can) = fs::canonicalize(&p) {
                fp = can.to_string_lossy().to_string();
            }
        }
        to_remove.push(fp);
    }
    db.retain(|e| !to_remove.contains(&e.path));
    if let Err(e) = write_db(&db) {
        eprintln!("zoxide: could not write database: {}", e);
        std::process::exit(1);
    }
}

fn query_score(rank: f64, last: u64, now: u64) -> f64 {
    let delta = now.saturating_sub(last);
    let factor = if delta < 3600 { 4.0 } else if delta < 86400 { 2.0 } else if delta < 604800 { 0.5 } else { 0.25 };
    rank * factor
}

fn matches_keywords(path: &str, keywords: &[String]) -> bool {
    if keywords.is_empty() { return true; }
    let path_lower = path.to_lowercase();
    let last_slash = path.rfind('/');
    let (parent, last_comp) = if let Some(idx) = last_slash {
        (&path[..idx], &path[idx+1..])
    } else {
        ("", path)
    };
    let parent_lower = parent.to_lowercase();
    let last_lower = last_comp.to_lowercase();

    if keywords.len() == 1 && keywords[0].ends_with('/') {
        let kw = keywords[0].trim_end_matches('/').to_lowercase();
        if kw.is_empty() { return true; }
        return parent_lower.ends_with(&kw);
    }

    let mut pos = 0usize;
    for (i, kw) in keywords.iter().enumerate() {
        let is_last = i == keywords.len() - 1;
        let kw_lower = kw.to_lowercase();
        let ends_slash = kw_lower.ends_with('/');
        if ends_slash {
            let x = kw_lower.trim_end_matches('/').to_string();
            if x.is_empty() {
                if let Some(idx) = path_lower[pos..].find('/') {
                    pos += idx + 1;
                } else {
                    return false;
                }
                continue;
            }
            if is_last {
                if !parent_lower.ends_with(&x) { return false; }
                if pos > parent_lower.len() { return false; }
            } else {
                let search = x.clone() + "/";
                if let Some(idx) = path_lower[pos..].find(&search) {
                    pos += idx + search.len();
                } else {
                    return false;
                }
            }
        } else {
            if kw_lower.contains('/') {
                // Find occurrence where last segment within last component if last
                let mut search_pos = pos;
                let mut found = false;
                while let Some(idx) = path_lower[search_pos..].find(&kw_lower) {
                    let abs_idx = search_pos + idx;
                    if is_last {
                        let last_slash_kw = kw_lower.rfind('/').unwrap();
                        let seg_start = abs_idx + last_slash_kw + 1;
                        let last_comp_start = path_lower.rfind('/').map(|j| j+1).unwrap_or(0);
                        if seg_start < last_comp_start { 
                            search_pos = abs_idx + 1;
                            continue;
                        }
                        let last_seg = kw_lower.rsplit('/').last().unwrap_or("");
                        if !last_lower.contains(last_seg) {
                            search_pos = abs_idx + 1;
                            continue;
                        }
                    }
                    pos = abs_idx + kw_lower.len();
                    found = true;
                    break;
                }
                if !found { return false; }
            } else {
                if is_last {
                    if !last_lower.contains(&kw_lower) { return false; }
                    // Find occurrence within last component after pos
                    let mut search_pos = pos;
                    let mut found = false;
                    while let Some(idx) = path_lower[search_pos..].find(&kw_lower) {
                        let abs_idx = search_pos + idx;
                        let last_comp_start = path_lower.rfind('/').map(|j| j+1).unwrap_or(0);
                        if abs_idx < last_comp_start {
                            search_pos = abs_idx + 1;
                            continue;
                        }
                        pos = abs_idx + kw_lower.len();
                        found = true;
                        break;
                    }
                    if !found { return false; }
                } else {
                    if let Some(idx) = path_lower[pos..].find(&kw_lower) {
                        pos += idx + kw_lower.len();
                    } else {
                        return false;
                    }
                }
            }
        }
    }
    true
}

fn query_dirs(args: QueryArgs) {
    let db = read_db();
    let now = current_timestamp();
    let mut entries: Vec<(DirEntry, f64)> = db.into_iter().map(|e| { let s = query_score(e.rank, e.last_accessed, now); (e, s)}).collect();
    entries.sort_by(|a,b| b.1.partial_cmp(&a.1).unwrap_or(std::cmp::Ordering::Equal));

    if let Some(base) = &args.base_dir {
        let base_lower = base.to_lowercase();
        entries.retain(|(e,_)| {
            let pl = e.path.to_lowercase();
            pl == base_lower || pl.starts_with(&(base_lower.clone() + "/"))
        });
    }
    if let Some(ex) = &args.exclude {
        entries.retain(|(e,_)| e.path != *ex);
    }
    if !args.keywords.is_empty() {
        entries.retain(|(e,_)| matches_keywords(&e.path, &args.keywords));
    }
    if !args.all {
        entries.retain(|(e,_)| Path::new(&e.path).is_dir());
    }
    if entries.is_empty() && !args.keywords.is_empty() {
        if !args.list && !args.interactive {
            eprintln!("zoxide: no match found");
            std::process::exit(1);
        }
    }
    if args.interactive {
        let fzf_opts = env::var("_ZO_FZF_OPTS").unwrap_or_default();
        let mut input = String::new();
        for (e, score) in &entries {
            if args.score {
                input.push_str(&format!("{:.1} {}\n", score, e.path));
            } else {
                input.push_str(&format!("{}\n", e.path));
            }
        }
        if entries.is_empty() {
            eprintln!("zoxide: no match found");
            std::process::exit(1);
        }
        let mut cmd = std::process::Command::new("fzf");
        if !fzf_opts.is_empty() {
            for opt in fzf_opts.split_whitespace() { cmd.arg(opt); }
        }
        cmd.stdin(std::process::Stdio::piped());
        cmd.stdout(std::process::Stdio::piped());
        cmd.stderr(std::process::Stdio::inherit());
        match cmd.spawn() {
            Ok(mut child) => {
                if let Some(stdin) = child.stdin.as_mut() {
                    let _ = stdin.write_all(input.as_bytes());
                }
                if let Ok(out) = child.wait_with_output() {
                    if !out.status.success() { std::process::exit(1); }
                    let selected = String::from_utf8_lossy(&out.stdout).trim().to_string();
                    let path = if args.score {
                        selected.splitn(2, ' ').nth(1).unwrap_or(&selected).trim().to_string()
                    } else { selected };
                    if path.is_empty() { std::process::exit(1); }
                    println!("{}", path);
                } else {
                    eprintln!("zoxide: failed to run fzf");
                    std::process::exit(1);
                }
            }
            Err(_) => {
                if let Some((e,_)) = entries.first() {
                    println!("{}", e.path);
                } else {
                    eprintln!("zoxide: no match found");
                    std::process::exit(1);
                }
            }
        }
        return;
    }
    if args.list {
        for (e, score) in entries {
            if args.score {
                println!("{:>8.1} {}", score, e.path);
            } else {
                println!("{}", e.path);
            }
        }
    } else {
        if let Some((e,_)) = entries.first() {
            println!("{}", e.path);
        }
    }
}

fn import_db(args: ImportArgs) {
    let from = args.from;
    let merge = args.merge;
    let import_path = args.path;
    let mut db = read_db();
    if !db.is_empty() && !merge {
        eprintln!("zoxide: current database is not empty, specify --merge to continue anyway");
        std::process::exit(1);
    }
    let content = match fs::read_to_string(&import_path) {
        Ok(c) => c,
        Err(_) => {
            eprintln!("zoxide: could not open database for importing: {}", import_path);
            eprintln!("\nCaused by:\n    No such file or directory (os error 2)");
            std::process::exit(1);
        }
    };
    let mut imported: Vec<DirEntry> = Vec::new();
    if from == "z" {
        for line in content.lines() {
            if line.trim().is_empty() { continue; }
            let parts: Vec<&str> = line.split('|').collect();
            if parts.len() != 3 { continue; }
            let path = parts[0].to_string();
            let rank: f64 = parts[1].parse().unwrap_or(0.0);
            let last: u64 = parts[2].parse().unwrap_or(0);
            imported.push(DirEntry { path, rank, last_accessed: last });
        }
        imported = dedup_db(imported);
    } else if from == "autojump" {
        for line in content.lines() {
            if line.trim().is_empty() { continue; }
            let parts: Vec<&str> = line.split('\t').collect();
            if parts.len() != 2 { continue; }
            let rank: f64 = parts[0].trim().parse().unwrap_or(0.0);
            let path = parts[1].trim().to_string();
            let sigmoid = 1.0 / (1.0 + (-rank).exp());
            imported.push(DirEntry { path, rank: sigmoid, last_accessed: 0 });
        }
        imported = dedup_db(imported);
    } else {
        eprintln!("unknown import type");
        std::process::exit(1);
    }
    if merge {
        for imp in imported {
            if let Some(existing) = db.iter_mut().find(|e| e.path == imp.path) {
                existing.rank += imp.rank;
                if imp.last_accessed > existing.last_accessed {
                    existing.last_accessed = imp.last_accessed;
                }
            } else {
                db.push(imp);
            }
        }
    } else {
        db = imported;
    }
    if let Err(e) = write_db(&db) {
        eprintln!("zoxide: could not write database: {}", e);
        std::process::exit(1);
    }
}

fn get_init_template(shell: &Shell, hook: &Hook, cmd: &str, no_cmd: bool) -> String {
    // For all shells, try to load from template files that we bundled.
    // The templates are stored in templates/ directory, with names like bash_pwd.txt, etc.
    // We will use include_str! for each.

    // Helper to get template content
    macro_rules! load_template {
        ($shell:expr, $hook:expr) => {
            match ($shell, $hook) {
                ("bash", "pwd") => include_str!("../templates/bash_pwd.txt"),
                ("bash", "prompt") => include_str!("../templates/bash_prompt.txt"),
                ("bash", "none") => include_str!("../templates/bash_none.txt"),
                ("zsh", "pwd") => include_str!("../templates/zsh_pwd.txt"),
                ("zsh", "prompt") => include_str!("../templates/zsh_prompt.txt"),
                ("zsh", "none") => include_str!("../templates/zsh_none.txt"),
                ("fish", "pwd") => include_str!("../templates/fish_pwd.txt"),
                ("fish", "prompt") => include_str!("../templates/fish_prompt.txt"),
                ("fish", "none") => include_str!("../templates/fish_none.txt"),
                ("posix", "pwd") => include_str!("../templates/posix_pwd.txt"),
                ("posix", "prompt") => include_str!("../templates/posix_prompt.txt"),
                ("posix", "none") => include_str!("../templates/posix_none.txt"),
                ("elvish", "pwd") => include_str!("../templates/elvish_pwd.txt"),
                ("elvish", "prompt") => include_str!("../templates/elvish_prompt.txt"),
                ("elvish", "none") => include_str!("../templates/elvish_none.txt"),
                ("nushell", "pwd") => include_str!("../templates/nushell_pwd.txt"),
                ("nushell", "prompt") => include_str!("../templates/nushell_prompt.txt"),
                ("nushell", "none") => include_str!("../templates/nushell_none.txt"),
                ("powershell", "pwd") => include_str!("../templates/powershell_pwd.txt"),
                ("powershell", "prompt") => include_str!("../templates/powershell_prompt.txt"),
                ("powershell", "none") => include_str!("../templates/powershell_none.txt"),
                ("tcsh", "pwd") => include_str!("../templates/tcsh_pwd.txt"),
                ("tcsh", "prompt") => include_str!("../templates/tcsh_prompt.txt"),
                ("tcsh", "none") => include_str!("../templates/tcsh_none.txt"),
                ("xonsh", "pwd") => include_str!("../templates/xonsh_pwd.txt"),
                ("xonsh", "prompt") => include_str!("../templates/xonsh_prompt.txt"),
                ("xonsh", "none") => include_str!("../templates/xonsh_none.txt"),
                _ => "",
            }
        };
    }

    let shell_str = match shell {
        Shell::Bash => "bash",
        Shell::Elvish => "elvish",
        Shell::Fish => "fish",
        Shell::Nushell => "nushell",
        Shell::Posix => "posix",
        Shell::Powershell => "powershell",
        Shell::Tcsh => "tcsh",
        Shell::Xonsh => "xonsh",
        Shell::Zsh => "zsh",
    };
    let hook_str = match hook {
        Hook::None => "none",
        Hook::Prompt => "prompt",
        Hook::Pwd => "pwd",
    };

    let base = load_template!(shell_str, hook_str).to_string();

    if no_cmd {
        let nocmd = match (shell_str, hook_str) {
            ("bash", "pwd") => include_str!("../templates/bash_pwd_nocmd.txt"),
            ("bash", "prompt") => include_str!("../templates/bash_prompt_nocmd.txt"),
            ("bash", "none") => include_str!("../templates/bash_none_nocmd.txt"),
            ("zsh", "pwd") => include_str!("../templates/zsh_pwd_nocmd.txt"),
            ("zsh", "prompt") => include_str!("../templates/zsh_prompt_nocmd.txt"),
            ("zsh", "none") => include_str!("../templates/zsh_none_nocmd.txt"),
            ("fish", "pwd") => include_str!("../templates/fish_pwd_nocmd.txt"),
            ("fish", "prompt") => include_str!("../templates/fish_prompt_nocmd.txt"),
            ("fish", "none") => include_str!("../templates/fish_none_nocmd.txt"),
            ("posix", "pwd") => include_str!("../templates/posix_pwd_nocmd.txt"),
            ("posix", "prompt") => include_str!("../templates/posix_prompt_nocmd.txt"),
            ("posix", "none") => include_str!("../templates/posix_none_nocmd.txt"),
            ("elvish", "pwd") => include_str!("../templates/elvish_pwd_nocmd.txt"),
            ("elvish", "prompt") => include_str!("../templates/elvish_prompt_nocmd.txt"),
            ("elvish", "none") => include_str!("../templates/elvish_none_nocmd.txt"),
            ("nushell", "pwd") => include_str!("../templates/nushell_pwd_nocmd.txt"),
            ("nushell", "prompt") => include_str!("../templates/nushell_prompt_nocmd.txt"),
            ("nushell", "none") => include_str!("../templates/nushell_none_nocmd.txt"),
            ("powershell", "pwd") => include_str!("../templates/powershell_pwd_nocmd.txt"),
            ("powershell", "prompt") => include_str!("../templates/powershell_prompt_nocmd.txt"),
            ("powershell", "none") => include_str!("../templates/powershell_none_nocmd.txt"),
            ("tcsh", "pwd") => include_str!("../templates/tcsh_pwd_nocmd.txt"),
            ("tcsh", "prompt") => include_str!("../templates/tcsh_prompt_nocmd.txt"),
            ("tcsh", "none") => include_str!("../templates/tcsh_none_nocmd.txt"),
            ("xonsh", "pwd") => include_str!("../templates/xonsh_pwd_nocmd.txt"),
            ("xonsh", "prompt") => include_str!("../templates/xonsh_prompt_nocmd.txt"),
            ("xonsh", "none") => include_str!("../templates/xonsh_none_nocmd.txt"),
            _ => "",
        };
        return nocmd.to_string();
    }

    if cmd == "z" {
        return base;
    }

    // For custom cmd, replace occurrences
    // We have templates for cmd j and cd, let's load them if available, else replace generically
    let custom = match (shell_str, hook_str, cmd) {
        ("bash", "pwd", "j") => include_str!("../templates/bash_pwd_cmdj.txt"),
        ("bash", "pwd", "cd") => include_str!("../templates/bash_pwd_cmdcd.txt"),
        ("bash", "prompt", "j") => include_str!("../templates/bash_prompt_cmdj.txt"),
        ("bash", "prompt", "cd") => include_str!("../templates/bash_prompt_cmdcd.txt"),
        ("bash", "none", "j") => include_str!("../templates/bash_none_cmdj.txt"),
        ("bash", "none", "cd") => include_str!("../templates/bash_none_cmdcd.txt"),
        ("zsh", "pwd", "j") => include_str!("../templates/zsh_pwd_cmdj.txt"),
        ("zsh", "pwd", "cd") => include_str!("../templates/zsh_pwd_cmdcd.txt"),
        ("zsh", "prompt", "j") => include_str!("../templates/zsh_prompt_cmdj.txt"),
        ("zsh", "prompt", "cd") => include_str!("../templates/zsh_prompt_cmdcd.txt"),
        ("zsh", "none", "j") => include_str!("../templates/zsh_none_cmdj.txt"),
        ("zsh", "none", "cd") => include_str!("../templates/zsh_none_cmdcd.txt"),
        ("fish", "pwd", "j") => include_str!("../templates/fish_pwd_cmdj.txt"),
        ("fish", "pwd", "cd") => include_str!("../templates/fish_pwd_cmdcd.txt"),
        ("fish", "prompt", "j") => include_str!("../templates/fish_prompt_cmdj.txt"),
        ("fish", "prompt", "cd") => include_str!("../templates/fish_prompt_cmdcd.txt"),
        ("fish", "none", "j") => include_str!("../templates/fish_none_cmdj.txt"),
        ("fish", "none", "cd") => include_str!("../templates/fish_none_cmdcd.txt"),
        ("posix", "pwd", "j") => include_str!("../templates/posix_pwd_cmdj.txt"),
        ("posix", "pwd", "cd") => include_str!("../templates/posix_pwd_cmdcd.txt"),
        ("posix", "prompt", "j") => include_str!("../templates/posix_prompt_cmdj.txt"),
        ("posix", "prompt", "cd") => include_str!("../templates/posix_prompt_cmdcd.txt"),
        ("posix", "none", "j") => include_str!("../templates/posix_none_cmdj.txt"),
        ("posix", "none", "cd") => include_str!("../templates/posix_none_cmdcd.txt"),
        ("elvish", "pwd", "j") => include_str!("../templates/elvish_pwd_cmdj.txt"),
        ("elvish", "pwd", "cd") => include_str!("../templates/elvish_pwd_cmdcd.txt"),
        ("elvish", "prompt", "j") => include_str!("../templates/elvish_prompt_cmdj.txt"),
        ("elvish", "prompt", "cd") => include_str!("../templates/elvish_prompt_cmdcd.txt"),
        ("elvish", "none", "j") => include_str!("../templates/elvish_none_cmdj.txt"),
        ("elvish", "none", "cd") => include_str!("../templates/elvish_none_cmdcd.txt"),
        ("nushell", "pwd", "j") => include_str!("../templates/nushell_pwd_cmdj.txt"),
        ("nushell", "pwd", "cd") => include_str!("../templates/nushell_pwd_cmdcd.txt"),
        ("nushell", "prompt", "j") => include_str!("../templates/nushell_prompt_cmdj.txt"),
        ("nushell", "prompt", "cd") => include_str!("../templates/nushell_prompt_cmdcd.txt"),
        ("nushell", "none", "j") => include_str!("../templates/nushell_none_cmdj.txt"),
        ("nushell", "none", "cd") => include_str!("../templates/nushell_none_cmdcd.txt"),
        ("powershell", "pwd", "j") => include_str!("../templates/powershell_pwd_cmdj.txt"),
        ("powershell", "pwd", "cd") => include_str!("../templates/powershell_pwd_cmdcd.txt"),
        ("powershell", "prompt", "j") => include_str!("../templates/powershell_prompt_cmdj.txt"),
        ("powershell", "prompt", "cd") => include_str!("../templates/powershell_prompt_cmdcd.txt"),
        ("powershell", "none", "j") => include_str!("../templates/powershell_none_cmdj.txt"),
        ("powershell", "none", "cd") => include_str!("../templates/powershell_none_cmdcd.txt"),
        ("tcsh", "pwd", "j") => include_str!("../templates/tcsh_pwd_cmdj.txt"),
        ("tcsh", "pwd", "cd") => include_str!("../templates/tcsh_pwd_cmdcd.txt"),
        ("tcsh", "prompt", "j") => include_str!("../templates/tcsh_prompt_cmdj.txt"),
        ("tcsh", "prompt", "cd") => include_str!("../templates/tcsh_prompt_cmdcd.txt"),
        ("tcsh", "none", "j") => include_str!("../templates/tcsh_none_cmdj.txt"),
        ("tcsh", "none", "cd") => include_str!("../templates/tcsh_none_cmdcd.txt"),
        ("xonsh", "pwd", "j") => include_str!("../templates/xonsh_pwd_cmdj.txt"),
        ("xonsh", "pwd", "cd") => include_str!("../templates/xonsh_pwd_cmdcd.txt"),
        ("xonsh", "prompt", "j") => include_str!("../templates/xonsh_prompt_cmdj.txt"),
        ("xonsh", "prompt", "cd") => include_str!("../templates/xonsh_prompt_cmdcd.txt"),
        ("xonsh", "none", "j") => include_str!("../templates/xonsh_none_cmdj.txt"),
        ("xonsh", "none", "cd") => include_str!("../templates/xonsh_none_cmdcd.txt"),
        _ => "",
    };
    if !custom.is_empty() {
        return custom.to_string();
    }

    // Generic replacement for other cmds
    let mut out = base;
    // Replace function names and aliases - generic
    // For bash/zsh/posix, replace "function z()" etc.
    // This is a best-effort for arbitrary cmd values
    out = out.replace("function z()", &format!("function {}()", cmd));
    out = out.replace("function z {", &format!("function {} {{", cmd));
    out = out.replace(" z() {", &format!(" {}() {{", cmd));
    out = out.replace("\\builtin unalias z ", &format!("\\builtin unalias {} ", cmd));
    out = out.replace("alias z=", &format!("alias {}=", cmd));
    out = out.replace("abbr --erase z", &format!("abbr --erase {}", cmd));
    out = out.replace("complete --command z", &format!("complete --command {}", cmd));
    out = out.replace("complete -F __zoxide_z_complete -o filenames -- z", &format!("complete -F __zoxide_z_complete -o filenames -- {}", cmd));
    out = out.replace("compdef __zoxide_z_complete z", &format!("compdef __zoxide_z_complete {}", cmd));
    out = out.replace("READLINE_LINE=\"z ", &format!("READLINE_LINE=\"{} ", cmd));
    out = out.replace("BUFFER=\"z ", &format!("BUFFER=\"{} ", cmd));
    out = out.replace("alias zi=", &format!("alias {}i=", cmd));
    out = out.replace("abbr --erase zi", &format!("abbr --erase {}i", cmd));
    out = out.replace("function zi(", &format!("function {}i(", cmd));
    out = out.replace("complete --command zi", &format!("complete --command {}i", cmd));
    out = out.replace("complete -r zi", &format!("complete -r {}i", cmd));
    out
}

fn main() {
    let cli = Cli::parse();
    if cli.command.is_none() {
        use clap::CommandFactory;
        let mut cmd = Cli::command();
        let _ = cmd.print_help();
        println!();
        return;
    }
    match cli.command.unwrap() {
        Commands::Add(args) => add_dirs(args.paths, args.score),
        Commands::Edit(_) => {
            let db = read_db();
            if db.is_empty() { return; }
            let fzf_exists = std::process::Command::new("fzf").arg("--version").output().is_ok();
            if !fzf_exists {
                eprintln!("zoxide: fzf not found, please install fzf");
                std::process::exit(1);
            }
            let now = current_timestamp();
            let mut input = String::new();
            for e in &db {
                let score = query_score(e.rank, e.last_accessed, now);
                input.push_str(&format!("{:.1} {}\n", score, e.path));
            }
            let fzf_opts = env::var("_ZO_FZF_OPTS").unwrap_or_default();
            let mut c = std::process::Command::new("fzf");
            c.arg("--multi");
            if !fzf_opts.is_empty() {
                for opt in fzf_opts.split_whitespace() { c.arg(opt); }
            }
            c.stdin(std::process::Stdio::piped());
            c.stdout(std::process::Stdio::piped());
            c.stderr(std::process::Stdio::inherit());
            if let Ok(mut child) = c.spawn() {
                if let Some(stdin) = child.stdin.as_mut() {
                    let _ = stdin.write_all(input.as_bytes());
                }
                if let Ok(out) = child.wait_with_output() {
                    if out.status.success() {
                        let selected = String::from_utf8_lossy(&out.stdout);
                        let mut to_remove = Vec::new();
                        for line in selected.lines() {
                            if let Some((_, path)) = line.split_once(' ') {
                                to_remove.push(path.trim().to_string());
                            } else {
                                to_remove.push(line.trim().to_string());
                            }
                        }
                        let mut new_db = db;
                        new_db.retain(|e| !to_remove.contains(&e.path));
                        let _ = write_db(&new_db);
                    }
                }
            }
        }
        Commands::Import(args) => import_db(args),
        Commands::Init(args) => {
            let tmpl = get_init_template(&args.shell, &args.hook, &args.cmd, args.no_cmd);
            print!("{}", tmpl);
        }
        Commands::Query(args) => query_dirs(args),
        Commands::Remove(args) => remove_dirs(args.paths),
    }
}
RS
"}

