fn print_edit_help() {
    println!("zoxide-edit 0.9.9\nAjeet D'Souza <98ajeet@gmail.com>\nhttps://github.com/ajeetdsouza/zoxide\n\nEdit the database\n\nUsage:\n  executable edit\n\nOptions:\n  -h, --help     Print help\n  -V, --version  Print version\n\nEnvironment variables:\n  _ZO_DATA_DIR          Path for zoxide data files\n  _ZO_ECHO              Print the matched directory before navigating to it when set to 1\n  _ZO_EXCLUDE_DIRS      List of directory globs to be excluded\n  _ZO_FZF_OPTS          Custom flags to pass to fzf\n  _ZO_MAXAGE            Maximum total age after which entries start getting deleted\n  _ZO_RESOLVE_SYMLINKS  Resolve symlinks when storing paths");
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() == 1 {
        print_help();
        return;
    }
    // Handle --help and --version globally
    if args.len() == 2 {
        match args[1].as_str() {
            "-h" | "--help" => { print_help(); return; },
            "-V" | "--version" => { println!("zoxide 0.9.9"); return; },
            _ => {}
        }
    }

    let subcmd = args[1].as_str();
    match subcmd {
        "add" => {
            // Check help
            if args.iter().any(|a| a == "-h" || a == "--help") {
                print_add_help();
                return;
            }
            if args.iter().any(|a| a == "-V" || a == "--version") {
                println!("zoxide-add 0.9.9");
                return;
            }
            let mut paths = Vec::new();
            let mut score: Option<f64> = None;
            let mut i = 2;
            while i < args.len() {
                let a = &args[i];
                if a == "-s" || a == "--score" {
                    i+=1;
                    if i < args.len() {
                        score = args[i].parse().ok();
                        i+=1;
                    } else {
                        eprintln!("error: a value is required for '--score <SCORE>' but none was supplied\n\nFor more information, try '--help'.");
                        std::process::exit(2);
                    }
                } else if a.starts_with("--score=") {
                    let v = a.trim_start_matches("--score=");
                    score = v.parse().ok();
                    i+=1;
                } else if a == "--" {
                    i+=1;
                    while i < args.len() {
                        paths.push(args[i].clone());
                        i+=1;
                    }
                    break;
                } else if a.starts_with('-') {
                    eprintln!("error: unexpected argument '{}' found\n\nUsage: executable add [OPTIONS] <PATHS>...\n\nFor more information, try '--help'.", a);
                    std::process::exit(2);
                } else {
                    paths.push(a.clone());
                    i+=1;
                }
            }
            if paths.is_empty() {
                eprintln!("error: the following required arguments were not provided:\n  <PATHS>...\n\nUsage: executable add <PATHS>...\n\nFor more information, try '--help'.");
                std::process::exit(2);
            }
            add_dirs(paths, score);
        }
        "edit" => {
            if args.iter().any(|a| a == "-h" || a == "--help") {
                print_edit_help();
                return;
            }
            if args.iter().any(|a| a == "-V" || a == "--version") {
                println!("zoxide-edit 0.9.9");
                return;
            }
            if args.len() > 2 {
                eprintln!("error: unexpected argument '{}' found\n\nUsage: executable edit\n\nFor more information, try '--help'.", args[2]);
                std::process::exit(2);
            }
            // Edit implementation
            let db = read_db();
            if db.is_empty() { return; }
            // Check fzf
            let fzf_exists = std::process::Command::new("fzf").arg("--version").output().is_ok();
            if !fzf_exists {
                eprintln!("zoxide: fzf not found, please install fzf");
                std::process::exit(1);
            }
            let now = current_timestamp();
            let mut input = String::new();
            for e in &db {
                let sc = query_score(e.rank, e.last_accessed, now);
                input.push_str(&format!("{:.1} {}\n", sc, e.path));
            }
            let fzf_opts = env::var("_ZO_FZF_OPTS").unwrap_or_default();
            let mut cmd = std::process::Command::new("fzf");
            cmd.arg("--multi");
            if !fzf_opts.is_empty() {
                for opt in fzf_opts.split_whitespace() { cmd.arg(opt); }
            }
            cmd.stdin(std::process::Stdio::piped());
            cmd.stdout(std::process::Stdio::piped());
            cmd.stderr(std::process::Stdio::inherit());
            if let Ok(mut child) = cmd.spawn() {
                if let Some(stdin) = child.stdin.as_mut() {
                    let _ = stdin.write_all(input.as_bytes());
                }
                if let Ok(out) = child.wait_with_output() {
                    if out.status.success() {
                        let selected = String::from_utf8_lossy(&out.stdout);
                        let mut to_remove = Vec::new();
                        for line in selected.lines() {
                            if let Some((_, path)) = line.split_once(' ') {
                                to_remove.push(path.trim().to_string());
                            } else {
                                to_remove.push(line.trim().to_string());
                            }
                        }
                        let mut new_db = db;
                        new_db.retain(|e| !to_remove.contains(&e.path));
                        let _ = write_db(&new_db);
                    }
                }
            }
        }
        "import" => {
            if args.iter().any(|a| a == "-h" || a == "--help") {
                print_import_help();
                return;
            }
            if args.iter().any(|a| a == "-V" || a == "--version") {
                println!("zoxide-import 0.9.9");
                return;
            }
            let mut from: Option<String> = None;
            let mut merge = false;
            let mut path: Option<String> = None;
            let mut i = 2;
            while i < args.len() {
                let a = &args[i];
                if a == "--from" {
                    i+=1;
                    if i < args.len() {
                        from = Some(args[i].clone());
                        i+=1;
                    } else {
                        eprintln!("error: a value is required for '--from <FROM>' but none was supplied\n\nFor more information, try '--help'.");
                        std::process::exit(2);
                    }
                } else if a.starts_with("--from=") {
                    from = Some(a.trim_start_matches("--from=").to_string());
                    i+=1;
                } else if a == "--merge" {
                    merge = true;
                    i+=1;
                } else if a.starts_with('-') {
                    eprintln!("error: unexpected argument '{}' found\n\nUsage: executable import [OPTIONS] --from <FROM> <PATH>\n\nFor more information, try '--help'.", a);
                    std::process::exit(2);
                } else {
                    if path.is_none() {
                        path = Some(a.clone());
                    } else {
                        eprintln!("error: unexpected argument '{}' found\n\nUsage: executable import [OPTIONS] --from <FROM> <PATH>\n\nFor more information, try '--help'.", a);
                        std::process::exit(2);
                    }
                    i+=1;
                }
            }
            if from.is_none() {
                eprintln!("error: the following required arguments were not provided:\n  --from <FROM>\n\nUsage: executable import --from <FROM> <PATH>\n\nFor more information, try '--help'.");
                std::process::exit(2);
            }
            if path.is_none() {
                eprintln!("error: the following required arguments were not provided:\n  <PATH>\n\nUsage: executable import --from <FROM> <PATH>\n\nFor more information, try '--help'.");
                std::process::exit(2);
            }
            let from_val = from.unwrap();
            if from_val != "z" && from_val != "autojump" {
                eprintln!("error: invalid value '{}' for '--from <FROM>'\n  [possible values: autojump, z]\n\nFor more information, try '--help'.", from_val);
                std::process::exit(2);
            }
            import_db(&from_val, merge, &path.unwrap());
        }
        "init" => {
            if args.iter().any(|a| a == "-h" || a == "--help") {
                print_init_help();
                return;
            }
            if args.iter().any(|a| a == "-V" || a == "--version") {
                println!("zoxide-init 0.9.9");
                return;
            }
            let mut shell: Option<String> = None;
            let mut cmd = "z".to_string();
            let mut hook = "pwd".to_string();
            let mut no_cmd = false;
            let mut i = 2;
            while i < args.len() {
                let a = &args[i];
                if a == "--no-cmd" {
                    no_cmd = true;
                    i+=1;
                } else if a == "--cmd" {
                    i+=1;
                    if i < args.len() {
                        cmd = args[i].clone();
                        i+=1;
                    } else {
                        eprintln!("error: a value is required for '--cmd <CMD>' but none was supplied\n\nFor more information, try '--help'.");
                        std::process::exit(2);
                    }
                } else if a.starts_with("--cmd=") {
                    cmd = a.trim_start_matches("--cmd=").to_string();
                    i+=1;
                } else if a == "--hook" {
                    i+=1;
                    if i < args.len() {
                        hook = args[i].clone();
                        i+=1;
                    } else {
                        eprintln!("error: a value is required for '--hook <HOOK>' but none was supplied\n\nFor more information, try '--help'.");
                        std::process::exit(2);
                    }
                } else if a.starts_with("--hook=") {
                    hook = a.trim_start_matches("--hook=").to_string();
                    i+=1;
                } else if a.starts_with('-') {
                    eprintln!("error: unexpected argument '{}' found\n\nUsage: executable init [OPTIONS] <SHELL>\n\nFor more information, try '--help'.", a);
                    std::process::exit(2);
                } else {
                    if shell.is_none() {
                        shell = Some(a.clone());
                    } else {
                        eprintln!("error: unexpected argument '{}' found\n\nUsage: executable init [OPTIONS] <SHELL>\n\nFor more information, try '--help'.", a);
                        std::process::exit(2);
                    }
                    i+=1;
                }
            }
            if shell.is_none() {
                eprintln!("error: the following required arguments were not provided:\n  <SHELL>\n\nUsage: executable init <SHELL>\n\nFor more information, try '--help'.");
                std::process::exit(2);
            }
            let shell_val = shell.unwrap();
            let valid_shells = ["bash","elvish","fish","nushell","posix","powershell","tcsh","xonsh","zsh"];
            if !valid_shells.contains(&shell_val.as_str()) {
                eprintln!("error: invalid value '{}' for '<SHELL>'\n  [possible values: bash, elvish, fish, nushell, posix, powershell, tcsh, xonsh, zsh]\n\nFor more information, try '--help'.", shell_val);
                std::process::exit(2);
            }
            let valid_hooks = ["none","prompt","pwd"];
            if !valid_hooks.contains(&hook.as_str()) {
                eprintln!("error: invalid value '{}' for '--hook <HOOK>'\n  [possible values: none, prompt, pwd]\n\nFor more information, try '--help'.", hook);
                std::process::exit(2);
            }
            let tmpl = get_init_template(&shell_val, &hook, &cmd, no_cmd);
            print!("{}", tmpl);
        }
        "query" => {
            if args.iter().any(|a| a == "-h" || a == "--help") {
                print_query_help();
                return;
            }
            if args.iter().any(|a| a == "-V" || a == "--version") {
                println!("zoxide-query 0.9.9");
                return;
            }
            let mut all = false;
            let mut interactive = false;
            let mut list = false;
            let mut score = false;
            let mut exclude: Option<String> = None;
            let mut base_dir: Option<String> = None;
            let mut keywords = Vec::new();
            let mut i = 2;
            while i < args.len() {
                let a = &args[i];
                if a == "-a" || a == "--all" {
                    all = true;
                    i+=1;
                } else if a == "-i" || a == "--interactive" {
                    interactive = true;
                    i+=1;
                } else if a == "-l" || a == "--list" {
                    list = true;
                    i+=1;
                } else if a == "-s" || a == "--score" {
                    score = true;
                    i+=1;
                } else if a == "--exclude" {
                    i+=1;
                    if i < args.len() {
                        if exclude.is_some() {
                            eprintln!("error: the argument '--exclude <path>' cannot be used multiple times\n\nUsage: executable query [OPTIONS] [KEYWORDS]...\n\nFor more information, try '--help'.");
                            std::process::exit(2);
                        }
                        exclude = Some(args[i].clone());
                        i+=1;
                    } else {
                        eprintln!("error: a value is required for '--exclude <path>' but none was supplied\n\nFor more information, try '--help'.");
                        std::process::exit(2);
                    }
                } else if a.starts_with("--exclude=") {
                    if exclude.is_some() {
                        eprintln!("error: the argument '--exclude <path>' cannot be used multiple times\n\nUsage: executable query [OPTIONS] [KEYWORDS]...\n\nFor more information, try '--help'.");
                        std::process::exit(2);
                    }
                    exclude = Some(a.trim_start_matches("--exclude=").to_string());
                    i+=1;
                } else if a == "--base-dir" {
                    i+=1;
                    if i < args.len() {
                        base_dir = Some(args[i].clone());
                        i+=1;
                    } else {
                        eprintln!("error: a value is required for '--base-dir <path>' but none was supplied\n\nFor more information, try '--help'.");
                        std::process::exit(2);
                    }
                } else if a.starts_with("--base-dir=") {
                    base_dir = Some(a.trim_start_matches("--base-dir=").to_string());
                    i+=1;
                } else if a == "--" {
                    i+=1;
                    while i < args.len() {
                        keywords.push(args[i].clone());
                        i+=1;
                    }
                    break;
                } else if a.starts_with('-') && a.len() > 1 && !a.starts_with("--") {
                    // Handle combined short flags like -als
                    let mut chars = a.chars().skip(1);
                    let mut handled = true;
                    for c in chars {
                        match c {
                            'a' => all = true,
                            'i' => interactive = true,
                            'l' => list = true,
                            's' => score = true,
                            _ => { handled = false; break; }
                        }
                    }
                    if !handled {
                        eprintln!("error: unexpected argument '{}' found\n\nUsage: executable query [OPTIONS] [KEYWORDS]...\n\nFor more information, try '--help'.", a);
                        std::process::exit(2);
                    }
                    i+=1;
                } else if a.starts_with('-') {
                    eprintln!("error: unexpected argument '{}' found\n\nUsage: executable query [OPTIONS] [KEYWORDS]...\n\nFor more information, try '--help'.", a);
                    std::process::exit(2);
                } else {
                    keywords.push(a.clone());
                    i+=1;
                }
            }
            query_dirs(all, interactive, list, score, exclude, base_dir, keywords);
        }
        "remove" => {
            if args.iter().any(|a| a == "-h" || a == "--help") {
                print_remove_help();
                return;
            }
            if args.iter().any(|a| a == "-V" || a == "--version") {
                println!("zoxide-remove 0.9.9");
                return;
            }
            let mut paths = Vec::new();
            let mut i = 2;
            while i < args.len() {
                let a = &args[i];
                if a == "--" {
                    i+=1;
                    while i < args.len() {
                        paths.push(args[i].clone());
                        i+=1;
                    }
                    break;
                } else if a.starts_with('-') {
                    eprintln!("error: unexpected argument '{}' found\n\nUsage: executable remove [PATHS]...\n\nFor more information, try '--help'.", a);
                    std::process::exit(2);
                } else {
                    paths.push(a.clone());
                    i+=1;
                }
            }
            remove_dirs(paths);
        }
        _ => {
            eprintln!("error: unrecognized subcommand '{}'\n\nUsage: executable <COMMAND>\n\nFor more information, try '--help'.", subcmd);
            std::process::exit(2);
        }
    }
}
