                        let last_comp_start = path_lower.rfind('/').map(|j| j+1).unwrap_or(0);
                        if seg_start < last_comp_start {
                            search_pos = abs_idx + 1;
                            continue;
                        }
                        let last_seg = kw_lower.rsplit('/').last().unwrap_or("");
                        if !last_lower.contains(last_seg) {
                            search_pos = abs_idx + 1;
                            continue;
                        }
                    }
                    found = Some(abs_idx);
                    break;
                }
                if found.is_none() { return false; }
                pos = found.unwrap() + kw_lower.len();
            } else {
                if is_last {
                    if !last_lower.contains(&kw_lower) { return false; }
                    let mut search_pos = pos;
                    let mut found = None;
                    while let Some(idx) = path_lower[search_pos..].find(&kw_lower) {
                        let abs_idx = search_pos + idx;
                        let last_comp_start = path_lower.rfind('/').map(|j| j+1).unwrap_or(0);
                        if abs_idx < last_comp_start {
                            search_pos = abs_idx + 1;
                            continue;
                        }
                        found = Some(abs_idx);
                        break;
                    }
                    if found.is_none() { return false; }
                    pos = found.unwrap() + kw_lower.len();
                } else {
                    if let Some(idx) = path_lower[pos..].find(&kw_lower) {
                        pos += idx + kw_lower.len();
                    } else { return false; }
                }
            }
        }
    }
    true
