    env['_ZO_DATA_DIR'] = TMPDIR
    result = subprocess.run(['./executable.new','query','--list','--all']+kws, env=env, capture_output=True, text=True)
    return sorted([line.strip() for line in result.stdout.splitlines() if line.strip()])

