                    diffs.append((shell,hook,cmd,no_cmd))
                    print(f"DIFF shell={shell} hook={hook} cmd={cmd} no_cmd={no_cmd} len old {len(old)} new {len(new)}")
                    # Write files
                    open(f"/tmp/old_{shell}_{hook}_{cmd}_{no_cmd}.txt","w").write(old)
                    open(f"/tmp/new_{shell}_{hook}_{cmd}_{no_cmd}.txt","w").write(new)

print(f"Total diffs: {len(diffs)}")

